"""Preprocessing functions for spectral and analytical data.This module contains functions for autoscaling, mean centering,Standard Normal Variate transformation, and Savitzky–Golay filtering."""import pandas as pdfrom scipy.signal import savgol_filter as _scipy_savgol_filter# =============================================================================# SCALING# =============================================================================def scale(df, method="auto"):    """    Scale a DataFrame column-wise.    Parameters    ----------    df : pandas.DataFrame        Data matrix with samples in rows and variables in columns.    method : {"none", "center", "auto", "pareto", "range"}, default="auto"        Scaling method.        "none"            Return the data without scaling.        "center"            Mean-center each variable:                x_scaled = x - mean(x)        "auto"            Mean-center each variable and divide by its standard            deviation:                x_scaled = (x - mean(x)) / std(x)        "pareto"            Mean-center each variable and divide by the square root            of its standard deviation:                x_scaled = (x - mean(x)) / sqrt(std(x))        "range"            Mean-center each variable and divide by its range:                x_scaled = (x - mean(x)) / (max(x) - min(x))    Returns    -------    pandas.DataFrame        Scaled data with the original index and columns preserved.    Examples    --------    >>> import pandas as pd    >>> import foodomicspy as f    >>>    >>> df = pd.DataFrame({    ...     "x1": [1.0, 2.0, 3.0],    ...     "x2": [10.0, 20.0, 30.0],    ... })    >>>    >>> df_scaled = f.preprocessing.scale(    ...     df,    ...     method="auto",    ... )    """    # -------------------------------------------------------------------------    # Validate input    # -------------------------------------------------------------------------    if not isinstance(df, pd.DataFrame):        raise TypeError(            "'df' must be a pandas DataFrame."        )    valid_methods = {        "none",        "center",        "auto",        "pareto",        "range",    }    method = str(method).lower()    if method not in valid_methods:        raise ValueError(            f"Unknown scaling method '{method}'. "            f"Choose from {sorted(valid_methods)}."        )    # -------------------------------------------------------------------------    # No scaling    # -------------------------------------------------------------------------    if method == "none":        return df.copy()    # -------------------------------------------------------------------------    # Mean centering    # -------------------------------------------------------------------------    mean = df.mean()    centered = (        df - mean    )    if method == "center":        return centered    # -------------------------------------------------------------------------    # Autoscaling    # -------------------------------------------------------------------------    if method == "auto":        std = df.std()        if (std == 0).any():            raise ValueError(                "Autoscaling cannot be performed because "                "one or more variables have zero standard deviation."            )        return (            centered / std        )    # -------------------------------------------------------------------------    # Pareto scaling    # -------------------------------------------------------------------------    if method == "pareto":        std = df.std()        if (std == 0).any():            raise ValueError(                "Pareto scaling cannot be performed because "                "one or more variables have zero standard deviation."            )        return (            centered / np.sqrt(std)        )    # -------------------------------------------------------------------------    # Range scaling    # -------------------------------------------------------------------------    if method == "range":        variable_range = (            df.max() - df.min()        )        if (variable_range == 0).any():            raise ValueError(                "Range scaling cannot be performed because "                "one or more variables have zero range."            )        return (            centered / variable_range        )# =============================================================================# MEAN CENTERING# =============================================================================def mean_center(df):    """    Mean-center a DataFrame column-wise.    The mean of each variable is subtracted from all observations    in that variable.    Parameters    ----------    df : pandas.DataFrame        Data matrix with samples in rows and variables in columns.    Returns    -------    pandas.DataFrame        Mean-centered data with the original index and columns preserved.    Examples    --------    >>> import pandas as pd    >>> import foodomicspy as f    >>> df = pd.DataFrame({    ...     "x1": [1.0, 2.0, 3.0],    ...     "x2": [10.0, 20.0, 30.0],    ... })    >>> df_centered = f.preprocessing.mean_center(df)    """    return df - df.mean()# =============================================================================# STANDARD NORMAL VARIATE# =============================================================================def snv(df):    """    Apply Standard Normal Variate transformation row-wise.    Each spectrum is centered using its own mean and scaled using    its own standard deviation.    Parameters    ----------    df : pandas.DataFrame        Spectral data with samples in rows and spectral variables        in columns.    Returns    -------    pandas.DataFrame        SNV-transformed spectra with the original index and columns        preserved.    Examples    --------    >>> import pandas as pd    >>> import foodomicspy as f    >>> df = pd.DataFrame(    ...     [    ...         [1.0, 2.0, 3.0, 4.0],    ...         [10.0, 12.0, 14.0, 16.0],    ...     ],    ...     index=["sample_1", "sample_2"],    ...     columns=[1000, 1001, 1002, 1003],    ... )    >>> df_snv = f.preprocessing.snv(df)    """    return df.sub(        df.mean(axis=1),        axis=0,    ).div(        df.std(axis=1),        axis=0,    )# =============================================================================# SAVITZKY-GOLAY FILTER# =============================================================================def savgol(    df,    window_length=15,    polyorder=2,    deriv=0,):    """    Apply Savitzky–Golay filtering to each spectrum.    Filtering is performed across the columns of each row. The function    can be used for smoothing or calculating spectral derivatives.    Parameters    ----------    df : pandas.DataFrame        Spectral data with samples in rows and spectral variables        in columns.    window_length : int, default=15        Number of spectral points in the filtering window. It must        usually be a positive odd integer.    polyorder : int, default=2        Order of the polynomial used to fit each filtering window.        It must be smaller than `window_length`.    deriv : int, default=0        Derivative order. Use 0 for smoothing, 1 for the first        derivative, or 2 for the second derivative.    Returns    -------    pandas.DataFrame        Filtered spectra with the original index and columns preserved.    Examples    --------    Smooth spectral data:    >>> import pandas as pd    >>> import foodomicspy as f    >>> df = pd.DataFrame(    ...     [    ...         [1.0, 1.3, 1.8, 2.4, 2.8, 3.1, 3.0],    ...         [2.0, 2.2, 2.7, 3.1, 3.5, 3.7, 3.6],    ...     ],    ...     index=["sample_1", "sample_2"],    ... )    >>> df_smoothed = f.preprocessing.savgol(    ...     df,    ...     window_length=5,    ...     polyorder=2,    ... )    Calculate the second derivative:    >>> df_derivative = f.preprocessing.savgol(    ...     df,    ...     window_length=5,    ...     polyorder=2,    ...     deriv=2,    ... )    """    filtered = _scipy_savgol_filter(        df.to_numpy(),        window_length=window_length,        polyorder=polyorder,        deriv=deriv,        axis=1,    )    return pd.DataFrame(        filtered,        index=df.index,        columns=df.columns,    )